import sys
from itertools import combinations

MOD = 998244353

def is_latin_square(arrays):
    n = len(arrays)
    for i in range(n):
        seen = [False] * (n + 1)
        for j in range(n):
            seen[arrays[j][i]] = True
        if not all(seen[1:]):
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    while t > 0:
        n = int(input[index])
        index += 1
        arrays = []
        for _ in range(2 * n):
            arrays.append(list(map(int, input[index:index + n])))
            index += n
        count = 0
        good_subset = None
        for subset in combinations(range(2 * n), n):
            if is_latin_square([arrays[i] for i in subset]):
                count += 1
                if good_subset is None:
                    good_subset = subset
        results.append((count % MOD, good_subset))
        t -= 1
    for count, subset in results:
        print(count)
        print(" ".join(map(str, [x + 1 for x in subset])))

if __name__ == "__main__":
    main()
